29	import org.springframework.http.HttpHeaders;
30	import org.springframework.http.HttpStatus;
31	import org.springframework.http.ResponseEntity;
32	import org.springframework.samples.petclinic.mapper.OwnerMapper;
33	import org.springframework.samples.petclinic.mapper.PetMapper;
34	import org.springframework.samples.petclinic.mapper.VisitMapper;
35	import org.springframework.samples.petclinic.model.Owner;
36	import org.springframework.samples.petclinic.model.Pet;
37	import org.springframework.samples.petclinic.model.Visit;
38	import org.springframework.samples.petclinic.rest.advice.DuplicateHouseholdException;
39	import org.springframework.samples.petclinic.rest.advice.DuplicateTelephoneException;
40	import org.springframework.samples.petclinic.rest.advice.InvalidRequestException;
41	import org.springframework.samples.petclinic.rest.api.OwnersApi;
42	import org.springframework.samples.petclinic.rest.dto.OwnerDto;
43	import org.springframework.samples.petclinic.rest.dto.OwnerFieldsDto;
44	import org.springframework.samples.petclinic.rest.dto.PetDto;
45	import org.springframework.samples.petclinic.rest.dto.PetFieldsDto;
46	import org.springframework.samples.petclinic.rest.dto.VisitDto;
47	import org.springframework.samples.petclinic.rest.dto.VisitFieldsDto;
48	import org.springframework.samples.petclinic.service.ClinicService;
49	import org.springframework.security.access.prepost.PreAuthorize;
50	import org.springframework.web.bind.annotation.CrossOrigin;
51	import org.springframework.web.bind.annotation.RequestMapping;
52	import org.springframework.web.bind.annotation.RestController;
53	import org.springframework.web.util.UriComponentsBuilder;
54	import org.springframework.util.StringUtils;
55	
56	import jakarta.transaction.Transactional;
57	
58	/**
59	 * @author Vitaliy Fedoriv
60	 */
61	
62	@RestController
63	@CrossOrigin(exposedHeaders = "errors, content-type")
64	@RequestMapping("/api")
65	public class OwnerRestControllerV1 implements OwnersApi {
66	
67	    /**
68	     * Syntactic email validation: a non-empty local part and a dotted domain, with no whitespace.
69	     * Matches addresses such as {@code test.user@example.com} and rejects strings without an '@'
70	     * and a dotted domain (e.g. {@code not-an-email}).
71	     */
72	    private static final Pattern EMAIL_PATTERN = Pattern.compile(
73	        "^[A-Za-z0-9!#$%&'*+/=?^_`{|}~-]+(?:\\.[A-Za-z0-9!#$%&'*+/=?^_`{|}~-]+)*"
74	            + "@(?:[A-Za-z0-9](?:[A-Za-z0-9-]*[A-Za-z0-9])?\\.)+[A-Za-z0-9](?:[A-Za-z0-9-]*[A-Za-z0-9])?$");
75	
76	    /** Default country code assumed for national numbers that carry no explicit '+' prefix. */
77	    private static final String DEFAULT_COUNTRY_CODE = "61";
78	
79	    /** Separators (spaces, dashes and brackets) stripped from a telephone before parsing. */
80	    private static final Pattern TELEPHONE_SEPARATORS = Pattern.compile("[\\s()\\[\\]-]");
81	
82	    /** A valid E.164 body: a leading '+' followed by 8 to 15 digits. */
83	    private static final Pattern E164_PATTERN = Pattern.compile("^\\+[0-9]{8,15}$");
84	
85	    /** Common street-type abbreviations expanded (on upper-cased tokens) during address normalization. */
86	    private static final Map<String, String> ADDRESS_ABBREVIATIONS = Map.of(
87	        "ST", "STREET",
88	        "RD", "ROAD",
89	        "AVE", "AVENUE");
90	
91	    private final ClinicService clinicService;
92	
93	    private final OwnerMapper ownerMapper;
94	
95	    private final PetMapper petMapper;
96	
97	    private final VisitMapper visitMapper;
98	
99	    public OwnerRestControllerV1(ClinicService clinicService,
100	                                 OwnerMapper ownerMapper,
101	                                 PetMapper petMapper,
102	                                 VisitMapper visitMapper) {
103	        this.clinicService = clinicService;
104	        this.ownerMapper = ownerMapper;
105	        this.petMapper = petMapper;
106	        this.visitMapper = visitMapper;
107	    }
108	
109	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
110	    @Override
111	    public ResponseEntity<List<OwnerDto>> listOwners(String lastName) {
112	        Collection<Owner> owners;
113	        if (lastName != null) {
114	            owners = this.clinicService.findOwnerByLastName(lastName);
115	        } else {
116	            owners = this.clinicService.findAllOwners();
117	        }
118	        if (owners.isEmpty()) {
119	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
120	        }
121	        return new ResponseEntity<>(ownerMapper.toOwnerDtoCollection(owners), HttpStatus.OK);
122	    }
123	
124	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
125	    @Override
126	    public ResponseEntity<OwnerDto> getOwner(Integer ownerId) {
127	        Owner owner = this.clinicService.findOwnerById(ownerId);
128	        if (owner == null) {
129	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
130	        }
131	        return new ResponseEntity<>(ownerMapper.toOwnerDto(owner), HttpStatus.OK);
132	    }
133	
134	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
135	    @Override
136	    public ResponseEntity<OwnerDto> addOwner(OwnerFieldsDto ownerFieldsDto) {
137	        List<String> missingFields = new ArrayList<>();
138	        if (!StringUtils.hasText(ownerFieldsDto.getFirstName())) {
139	            missingFields.add("firstName");
140	        }
141	        if (!StringUtils.hasText(ownerFieldsDto.getLastName())) {
142	            missingFields.add("lastName");
143	        }
144	        // Normalize the address up front; the required-field check rejects it when it is blank
145	        // after normalization (e.g. a whitespace-only value collapses to the empty string).
146	        String normalizedAddress = normalizeAddress(ownerFieldsDto.getAddress());
147	        if (!StringUtils.hasText(normalizedAddress)) {
148	            missingFields.add("address");
149	        }
150	        if (!StringUtils.hasText(ownerFieldsDto.getCity())) {
151	            missingFields.add("city");
152	        }
153	        if (!StringUtils.hasText(ownerFieldsDto.getTelephone())) {
154	            missingFields.add("telephone");
155	        }
156	        if (!missingFields.isEmpty()) {
157	            throw new InvalidRequestException(missingFields);
158	        }
159	        HttpHeaders headers = new HttpHeaders();
160	        Owner owner = ownerMapper.toOwner(ownerFieldsDto);
161	        // Store (and later return) the normalized address computed above.
162	        owner.setAddress(normalizedAddress);
163	        // Normalize the telephone into E.164 form (reject with 400 when it cannot form a valid one).
164	        String normalizedTelephone = normalizeTelephone(owner.getTelephone());
165	        owner.setTelephone(normalizedTelephone);
166	        // Normalize the (optional) email: reject a syntactically invalid address, otherwise store it lower-cased.
167	        owner.setEmail(normalizeEmail(owner.getEmail()));
168	        // Default the (optional) registration date to the server's current date when none was supplied.
169	        if (owner.getRegistrationDate() == null) {
170	            owner.setRegistrationDate(LocalDate.now());
171	        }
172	        // Reject the request if the E.164 telephone is already used by another owner.
173	        if (!this.clinicService.findOwnerByTelephone(normalizedTelephone).isEmpty()) {
174	            throw new DuplicateTelephoneException(normalizedTelephone);
175	        }
176	        // Reject the request if another owner already shares the same last name and address
177	        // (compared case-insensitively with collapsed whitespace), unless the caller opts in
178	        // by setting 'sharesHousehold' true. When they do opt in and an existing household is
179	        // matched, assign a stable shared 'householdId' to the new owner and backfill it onto
180	        // every existing member that does not yet carry it.
181	        List<Owner> householdMembers = findHouseholdMembers(owner.getLastName(), owner.getAddress());
182	        if (!householdMembers.isEmpty()) {
183	            if (!Boolean.TRUE.equals(ownerFieldsDto.getSharesHousehold())) {
184	                throw new DuplicateHouseholdException(owner.getLastName(), owner.getAddress());
185	            }
186	            String householdId = generateHouseholdId(owner.getLastName(), owner.getAddress());
187	            owner.setHouseholdId(householdId);
188	            for (Owner member : householdMembers) {
189	                if (!householdId.equals(member.getHouseholdId())) {
190	                    member.setHouseholdId(householdId);
191	                    this.clinicService.saveOwner(member);
192	                }
193	            }
194	        }
195	        // Record how many existing owners already share this first name and last name
196	        // (compared case-insensitively) before this owner is created.
197	        owner.setNamesakeCount(countNamesakes(owner.getFirstName(), owner.getLastName()));
198	        // Assign the customer code '<CITY3>-<LAST3>-<NNNN>' before persisting.
199	        owner.setCustomerCode(generateCustomerCode(owner.getCity(), owner.getLastName()));
200	        // Assign the membership number '<customerCode>-M<YY>' where YY is the last two
201	        // digits of the registration date year (e.g. 'SYD-SMI-0007-M26').
202	        owner.setMembershipNumber(generateMembershipNumber(owner.getCustomerCode(), owner.getRegistrationDate()));
203	        this.clinicService.saveOwner(owner);
204	        OwnerDto ownerDto = ownerMapper.toOwnerDto(owner);
205	        headers.setLocation(UriComponentsBuilder.newInstance()
206	            .path("/api/owners/{id}").buildAndExpand(owner.getId()).toUri());
207	        return new ResponseEntity<>(ownerDto, headers, HttpStatus.CREATED);
208	    }
209	
210	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
211	    @Override
212	    public ResponseEntity<OwnerDto> updateOwner(Integer ownerId, OwnerFieldsDto ownerFieldsDto) {
213	        Owner currentOwner = this.clinicService.findOwnerById(ownerId);
214	        if (currentOwner == null) {
215	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
216	        }
217	        currentOwner.setAddress(ownerFieldsDto.getAddress());
218	        currentOwner.setCity(ownerFieldsDto.getCity());
219	        currentOwner.setFirstName(ownerFieldsDto.getFirstName());
220	        currentOwner.setLastName(ownerFieldsDto.getLastName());
221	        currentOwner.setTelephone(ownerFieldsDto.getTelephone());
222	        currentOwner.setEmail(normalizeEmail(ownerFieldsDto.getEmail()));
223	        this.clinicService.saveOwner(currentOwner);
224	        return new ResponseEntity<>(ownerMapper.toOwnerDto(currentOwner), HttpStatus.NO_CONTENT);
225	    }
226	
227	    /**
228	     * Generate a customer code formatted {@code <CITY3>-<LAST3>-<NNNN>}, where {@code CITY3} is the
229	     * upper-cased first three letters of {@code city}, {@code LAST3} is the upper-cased first three
230	     * letters of {@code lastName} and {@code NNNN} is a per-city 4-digit zero-padded sequence equal to
231	     * one more than the current number of owners already in that city (e.g. {@code SYD-SMI-0007}).
232	     *
233	     * @param city     the owner's city
234	     * @param lastName the owner's last name
235	     * @return the generated customer code
236	     */
237	    private String generateCustomerCode(String city, String lastName) {
238	        String cityPrefix = city.length() >= 3 ? city.substring(0, 3) : city;
239	        String lastPrefix = lastName.length() >= 3 ? lastName.substring(0, 3) : lastName;
240	        String normalizedCity = normalizeForComparison(city);
241	        int sequence = (int) this.clinicService.findAllOwners().stream()
242	            .filter(existing -> normalizeForComparison(existing.getCity()).equals(normalizedCity))
243	            .count() + 1;
244	        return String.format("%s-%s-%04d", cityPrefix.toUpperCase(Locale.ROOT),
245	            lastPrefix.toUpperCase(Locale.ROOT), sequence);
246	    }
247	
248	    /**
249	     * Generate a membership number formatted {@code <customerCode>-M<YY>}, where {@code YY} is the
250	     * last two digits of the {@code registrationDate} year (e.g. {@code SYD-SMI-0007-M26}).
251	     *
252	     * @param customerCode     the owner's already-assigned customer code
253	     * @param registrationDate the owner's registration date
254	     * @return the generated membership number
255	     */
256	    private String generateMembershipNumber(String customerCode, LocalDate registrationDate) {
257	        String yy = String.format("%02d", registrationDate.getYear() % 100);
258	        return String.format("%s-M%s", customerCode, yy);
259	    }
260	
261	    /**
262	     * Count the existing owners that share the given first name and last name, comparing each
263	     * case-insensitively (trimmed, with internal whitespace collapsed). The incoming owner is not
264	     * yet persisted, so it is not included in the count.
265	     *
266	     * @param firstName the incoming owner's first name
267	     * @param lastName  the incoming owner's last name
268	     * @return the number of existing namesakes
269	     */
270	    private int countNamesakes(String firstName, String lastName) {
271	        String normalizedFirstName = normalizeForComparison(firstName);
272	        String normalizedLastName = normalizeForComparison(lastName);
273	        return (int) this.clinicService.findAllOwners().stream()
274	            .filter(existing -> normalizeForComparison(existing.getFirstName()).equals(normalizedFirstName)
275	                && normalizeForComparison(existing.getLastName()).equals(normalizedLastName))
276	            .count();
277	    }
278	
279	    /**
280	     * Find the existing owners that live in the same household as the given values, i.e. those that
281	     * share both the last name and the address when each is compared case-insensitively with
282	     * collapsed whitespace.
283	     *
284	     * @param lastName the incoming owner's last name
285	     * @param address  the incoming owner's address
286	     * @return the matching existing owners (possibly empty)
287	     */
288	    private List<Owner> findHouseholdMembers(String lastName, String address) {
289	        String normalizedLastName = normalizeForComparison(lastName);
290	        String normalizedAddress = normalizeForComparison(address);
291	        return this.clinicService.findAllOwners().stream()
292	            .filter(existing -> normalizeForComparison(existing.getLastName()).equals(normalizedLastName)
293	                && normalizeForComparison(existing.getAddress()).equals(normalizedAddress))
294	            .toList();
295	    }
296	
297	    /**
298	     * Generate a stable shared household identifier for the given last name and address. The value is
299	     * derived deterministically from the normalized (case-insensitive, whitespace-collapsed) last name
300	     * and address, so every owner joining the same household resolves to the same identifier. It is the
301	     * first 12 upper-case hex characters of the SHA-256 digest of {@code <lastName>|<address>}.
302	     *
303	     * @param lastName the household's last name
304	     * @param address  the household's address
305	     * @return the stable household identifier
306	     */
307	    private String generateHouseholdId(String lastName, String address) {
308	        String key = normalizeForComparison(lastName) + "|" + normalizeForComparison(address);
309	        try {
310	            byte[] digest = MessageDigest.getInstance("SHA-256")
311	                .digest(key.getBytes(StandardCharsets.UTF_8));
312	            StringBuilder sb = new StringBuilder(digest.length * 2);
313	            for (byte b : digest) {
314	                sb.append(String.format("%02x", b));
315	            }
316	            return sb.substring(0, 12).toUpperCase(Locale.ROOT);
317	        } catch (java.security.NoSuchAlgorithmException e) {
318	            throw new IllegalStateException("SHA-256 not available", e);
319	        }
320	    }
321	
322	    /**
323	     * Normalize an owner address for storage: trim and collapse every internal run of whitespace to a
324	     * single space, upper-case the result and expand common street-type abbreviations token by token
325	     * ({@code ST -> STREET}, {@code RD -> ROAD}, {@code AVE -> AVENUE}). A {@code null} value normalizes
326	     * to the empty string. The result is the canonical form that is stored, returned and used for every
327	     * address comparison (household duplicate detection and the shared household id).
328	     *
329	     * @param address the raw address, may be {@code null}
330	     * @return the normalized address
331	     */
332	    private String normalizeAddress(String address) {
333	        if (address == null) {
334	            return "";
335	        }
336	        String collapsed = address.trim().replaceAll("\\s+", " ").toUpperCase(Locale.ROOT);
337	        if (collapsed.isEmpty()) {
338	            return "";
339	        }
340	        String[] tokens = collapsed.split(" ");
341	        StringBuilder sb = new StringBuilder(collapsed.length());
342	        for (int i = 0; i < tokens.length; i++) {
343	            if (i > 0) {
344	                sb.append(' ');
345	            }
346	            sb.append(ADDRESS_ABBREVIATIONS.getOrDefault(tokens[i], tokens[i]));
347	        }
348	        return sb.toString();
349	    }
350	
351	    /**
352	     * Normalize a value for identity comparison: trim, collapse every internal run of whitespace to a
353	     * single space and lower-case the result. A {@code null} value normalizes to the empty string.
354	     *
355	     * @param value the raw value, may be {@code null}
356	     * @return the normalized value
357	     */
358	    private String normalizeForComparison(String value) {
359	        if (value == null) {
360	            return "";
361	        }
362	        return value.trim().replaceAll("\\s+", " ").toLowerCase(Locale.ROOT);
363	    }
364	
365	    /**
366	     * Normalize an optional owner email address. A blank/absent value is treated as "not provided"
367	     * and returns {@code null}. When present, the value must be a syntactically valid address; if it
368	     * is not, an {@link InvalidRequestException} is thrown (mapped to 400 Bad Request). A valid value
369	     * is returned lower-cased.
370	     *
371	     * @param email the raw email from the request payload, may be {@code null}
372	     * @return the lower-cased email, or {@code null} when none was provided
373	     */
374	    private String normalizeEmail(String email) {
375	        if (!StringUtils.hasText(email)) {
376	            return null;
377	        }
378	        if (!EMAIL_PATTERN.matcher(email).matches()) {
379	            throw new InvalidRequestException(List.of("email"));
380	        }
381	        return email.toLowerCase(Locale.ROOT);
382	    }
383	
384	    /**
385	     * Normalize a telephone into E.164 form. Spaces, dashes and brackets are stripped. A value that
386	     * already carries a leading '+' keeps its country code; otherwise the default country code
387	     * ({@code +61}) is assumed and a single leading '0' is dropped from the national digits. The
388	     * result must be a '+' followed by 8 to 15 digits, otherwise an {@link InvalidRequestException}
389	     * is thrown (mapped to 400 Bad Request).
390	     *
391	     * @param telephone the raw telephone from the request payload
392	     * @return the E.164 string (e.g. {@code +61412345678})
393	     */
394	    private String normalizeTelephone(String telephone) {
395	        String cleaned = TELEPHONE_SEPARATORS.matcher(telephone).replaceAll("");
396	        String candidate;
397	        if (cleaned.startsWith("+")) {
398	            candidate = cleaned;
399	        } else {
400	            String national = cleaned.startsWith("0") ? cleaned.substring(1) : cleaned;
401	            candidate = "+" + DEFAULT_COUNTRY_CODE + national;
402	        }
403	        if (!E164_PATTERN.matcher(candidate).matches()) {
404	            throw new InvalidRequestException(List.of("telephone"));
405	        }
406	        return candidate;
407	    }
408	
409	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
410	    @Transactional
411	    @Override
412	    public ResponseEntity<OwnerDto> deleteOwner(Integer ownerId) {
413	        Owner owner = this.clinicService.findOwnerById(ownerId);
414	        if (owner == null) {
415	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
416	        }
417	        this.clinicService.deleteOwner(owner);
418	        return new ResponseEntity<>(HttpStatus.NO_CONTENT);
419	    }
420	
421	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
422	    @Override
423	    public ResponseEntity<PetDto> addPetToOwner(Integer ownerId, PetFieldsDto petFieldsDto) {
424	        Owner owner = this.clinicService.findOwnerById(ownerId);
425	        if (owner == null) {
426	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
427	        }
428	        HttpHeaders headers = new HttpHeaders();
429	        Pet pet = petMapper.toPet(petFieldsDto);
430	        owner.setId(ownerId);
431	        pet.setOwner(owner);
432	        pet.getType().setName(null);
433	        this.clinicService.savePet(pet);
434	        PetDto petDto = petMapper.toPetDto(pet);
435	        headers.setLocation(UriComponentsBuilder.newInstance().path("/api/pets/{id}")
436	            .buildAndExpand(pet.getId()).toUri());
437	        return new ResponseEntity<>(petDto, headers, HttpStatus.CREATED);
438	    }
439	
440	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
441	    @Override
442	    public ResponseEntity<Void> updateOwnersPet(Integer ownerId, Integer petId, PetFieldsDto petFieldsDto) {
443	        Owner currentOwner = this.clinicService.findOwnerById(ownerId);
444	        if (currentOwner != null) {
445	            Pet currentPet = this.clinicService.findPetById(petId);
446	            if (currentPet != null) {
447	                currentPet.setBirthDate(petFieldsDto.getBirthDate());
448	                currentPet.setName(petFieldsDto.getName());
449	                currentPet.setType(petMapper.toPetType(petFieldsDto.getType()));
450	                this.clinicService.savePet(currentPet);
451	                return new ResponseEntity<>(HttpStatus.NO_CONTENT);
452	            }
453	        }
454	        return new ResponseEntity<>(HttpStatus.NOT_FOUND);
455	    }
456	
457	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
458	    @Override
459	    public ResponseEntity<VisitDto> addVisitToOwner(Integer ownerId, Integer petId, VisitFieldsDto visitFieldsDto) {
460	        HttpHeaders headers = new HttpHeaders();
461	        Visit visit = visitMapper.toVisit(visitFieldsDto);
462	        Pet pet = new Pet();
463	        pet.setId(petId);
464	        visit.setPet(pet);
465	        this.clinicService.saveVisit(visit);
466	        VisitDto visitDto = visitMapper.toVisitDto(visit);
467	        headers.setLocation(UriComponentsBuilder.newInstance().path("/api/visits/{id}")
468	            .buildAndExpand(visit.getId()).toUri());
469	        return new ResponseEntity<>(visitDto, headers, HttpStatus.CREATED);
470	    }
471	
472	
473	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
474	    @Override
475	    public ResponseEntity<PetDto> getOwnersPet(Integer ownerId, Integer petId) {
476	        Owner owner = this.clinicService.findOwnerById(ownerId);
477	        if (owner != null) {
478	            Pet pet = owner.getPet(petId);
479	            if (pet != null) {
480	                return new ResponseEntity<>(petMapper.toPetDto(pet), HttpStatus.OK);
481	            }
482	        }
483	        return new ResponseEntity<>(HttpStatus.NOT_FOUND);
484	    }
485	}
